<?php
namespace App\Controllers;
use App\Services\PaymentComplementDraftService;
use App\Services\PaymentComplementFiscalSnapshotService;
use App\Services\PaymentComplementReadinessService;
use App\Services\Fiscal\FiscalIssueDateNormalizer;
use App\Services\Fiscal\FiscalIssueDatePolicy;
use App\FiscalServices\PaymentComplementPreflightService;
use App\FiscalServices\PaymentComplementStampingService;
use App\FiscalServices\PaymentComplementPrintDataBuilder;
use App\FiscalServices\PaymentComplementCancellationService;
use App\Services\Fiscal\Pac\FiscalPacAdapterFactory;
use App\Services\Fiscal\Pdf\FiscalPdfTemplateResolver;
use CodeIgniter\Exceptions\PageNotFoundException;

class Payment_complements extends Security_Controller
{
    private function service():PaymentComplementDraftService{return new PaymentComplementDraftService(db_connect());}
    public function index(){return$this->template->rander('payment_complements/index',['configure_pdf_allowed'=>$this->allowed('fiscal_pdf_templates_manage')]);}
    public function list_data(){$db=db_connect();$rows=$db->table('payment_complements c')->select('c.id,c.issue_date,c.status,c.fiscal_document_id,cl.company_name,MAX(p.source_invoice_payment_id) source_invoice_payment_id,MAX(ip.amount) received_amount,MAX(p.amount) included_amount',false)->join('clients cl','cl.id=c.client_id')->join('payment_complement_payments p','p.payment_complement_id=c.id AND p.deleted=0','left')->join('invoice_payments ip','ip.id=p.source_invoice_payment_id','left')->where('c.deleted',0)->groupBy('c.id,c.issue_date,c.status,c.fiscal_document_id,cl.company_name')->orderBy('c.id','DESC')->get()->getResult();$out=[];foreach($rows as$r){$stamp=$r->fiscal_document_id?$db->table('fiscal_document_stamps')->where('fiscal_document_id',$r->fiscal_document_id)->get(1)->getRow():null;$cancel=$r->fiscal_document_id?$db->table('fiscal_cancellation_requests')->where('fiscal_document_id',$r->fiscal_document_id)->orderBy('id','DESC')->get(1)->getRow():null;$fiscal=$r->fiscal_document_id?$db->table('fiscal_documents')->where('id',$r->fiscal_document_id)->get(1)->getRow():null;$status=['draft'=>'Borrador incompleto','complete_draft'=>'Borrador completo','stamped'=>'Timbrado','cancelled'=>'Descartado'][$r->status]??$r->status;if(($fiscal->status??'')==='cancelled')$status='Cancelado fiscalmente';$cancelLabel=match($cancel->status??''){'sending','pending','unknown'=>'En proceso','accepted'=>'Cancelado','rejected','transport_not_sent'=>'Rechazada',default=>'No solicitada'};$actions='<a class="btn btn-default btn-sm" href="'.site_url('payment_complements/edit/'.$r->id).'">Ver</a>';if($r->status==='stamped'&&$stamp){$actions.=' <a class="btn btn-default btn-sm" target="_blank" href="'.site_url('fiscal/documents/'.$r->fiscal_document_id.'/pdf/preview').'">PDF</a> <a class="btn btn-default btn-sm" href="'.site_url('fiscal/stamping/xml/download/'.$r->fiscal_document_id).'">XML</a>';if(!empty($stamp->uuid)&&!empty($stamp->stamped_xml_artifact_id)&&$this->allowed('fiscal_pdf_generate')&&$this->allowed('fiscal.advanced.regenerate_pdf')){try{$template=(new FiscalPdfTemplateResolver())->resolve((int)$fiscal->issuer_profile_id,(string)config('FiscalPdfProvider')->provider,'P')->templateCode;}catch(\Throwable){$template='-';}$actions.=' '.js_anchor('Regenerar PDF',['class'=>'btn btn-warning btn-sm fiscal-regenerate-pdf','data-document-id'=>$r->fiscal_document_id,'data-document-label'=>'Complemento #'.$r->id,'data-uuid'=>$stamp->uuid,'data-template'=>$template]);}if((!$cancel||in_array($cancel->status,['rejected','transport_not_sent'],true))&&$this->allowed('fiscal_invoices_cancel'))$actions.=' '.modal_anchor(get_uri('payment_complements/cancel/form'),'Cancelar',['class'=>'btn btn-danger btn-sm','title'=>'Cancelar Complemento de Pago','data-post-complement_id'=>$r->id]);elseif($cancel&&in_array($cancel->status,['sending','pending','unknown'],true)&&$this->allowed('fiscal_status_query'))$actions.=' '.modal_anchor(get_uri('payment_complements/cancel/status/form'),'Verificar cancelación',['class'=>'btn btn-warning btn-sm','title'=>'Verificar cancelación','data-post-complement_id'=>$r->id]);elseif($cancel&&$cancel->status==='accepted'&&$this->allowed('fiscal_invoices_view_cancellation'))$actions.=' <a class="btn btn-default btn-sm" href="'.site_url('payment_complements/'.$r->id.'/cancel/receipt/'.$cancel->id).'">Acuse</a>';}$out[]=['#'.$r->id,esc($r->issue_date),esc($r->company_name),'Pago #'.(int)$r->source_invoice_payment_id,to_currency($r->received_amount??0),esc($stamp->uuid??'-'),esc($status),esc($cancelLabel),$actions];}return$this->response->setJSON(['data'=>$out]);}
    public function create(){$clients=db_connect()->table('clients')->select('id,company_name,vat_number')->where('deleted',0)->orderBy('company_name')->get()->getResult();return$this->template->view('payment_complements/client_form',['clients'=>$clients]);}
    public function save(){try{$clientId=(int)$this->request->getPost('client_id');$paymentId=(int)$this->request->getPost('invoice_payment_id');if(!$clientId)throw new \RuntimeException('Seleccione un cliente.');if(!$paymentId)throw new \RuntimeException('Seleccione un pago administrativo.');$id=$this->service()->createFromPayment($clientId,$paymentId,$this->login_user->id);return$this->response->setJSON(['success'=>true,'redirect_url'=>site_url('payment_complements/edit/'.$id)]);}catch(\Throwable$e){return$this->response->setStatusCode(422)->setJSON(['success'=>false,'message'=>$e->getMessage()]);}}
    public function clientPayments(int$clientId){$results=[];foreach($this->service()->candidatePayments($clientId)as$p)$results[]=['id'=>(int)$p->id,'text'=>'Pago #'.$p->id.' — '.$p->payment_date.' | '.to_currency($p->amount).' | '.($p->payment_method?:'Sin forma').' | '.($p->account_name?:'Sin cuenta').' | Aplicado: '.to_currency($p->applied_amount).' | Disponible: '.to_currency($p->available_amount),'applied_amount'=>$p->applied_amount,'available_amount'=>$p->available_amount];return$this->response->setJSON(['results'=>$results]);}
    public function edit(int$id){try{$service=$this->service();$data=$service->context($id);$data['candidate_empty_reason']=$data['candidates']?null:$service->emptyEligibilityReason((int)$data['payment']->source_invoice_payment_id);}catch(\Throwable){throw PageNotFoundException::forPageNotFound();}$db=db_connect();$inspection=(new PaymentComplementPreflightService($db))->inspect($id);$data['readiness']=$inspection['review'];$data['readiness']['ready']=$inspection['ready'];$factory=new FiscalPacAdapterFactory();$data['pac_environment']=$factory->environment();$data['can_stamp']=$this->canStamp();$data['stamp']=$data['complement']->fiscal_document_id?$db->table('fiscal_document_stamps')->where('fiscal_document_id',$data['complement']->fiscal_document_id)->get(1)->getRow():null;$data['cancellation']=$data['complement']->status==='stamped'?(new PaymentComplementCancellationService($db))->context($id):null;$data['can_cancel']=$this->allowed('fiscal_invoices_cancel');$data['can_check_cancellation']=$this->allowed('fiscal_status_query');$data['can_view_cancellation_receipt']=$this->allowed('fiscal_invoices_view_cancellation');$data['can_regenerate_pdf']=$this->allowed('fiscal_pdf_generate')&&$this->allowed('fiscal.advanced.regenerate_pdf');$data['configure_pdf_allowed']=$this->allowed('fiscal_pdf_templates_manage');return$this->template->rander('payment_complements/edit',$data);}
    public function updateDetails(int$id){$db=db_connect();try{$date=(new FiscalIssueDateNormalizer())->normalizeTransport($this->request->getPost('issue_date'));(new FiscalIssueDatePolicy())->validate($date);$form=trim((string)$this->request->getPost('payment_form_code'));$sat=$db->table('sat_payment_forms')->where(['code'=>$form,'is_active'=>1])->get(1)->getRow();if(!$sat)throw new \RuntimeException('Seleccione una Forma de pago SAT activa.');$db->transBegin();$header=$db->query('SELECT * FROM '.$db->prefixTable('payment_complements').' WHERE id=? FOR UPDATE',[$id])->getRow();if(!$header||!in_array($header->status,['draft','complete_draft'],true))throw new \RuntimeException('El borrador ya no es editable.');$payment=$db->query('SELECT * FROM '.$db->prefixTable('payment_complement_payments').' WHERE payment_complement_id=? AND deleted=0 FOR UPDATE',[$id])->getRow();if(!$payment)throw new \RuntimeException('No existe el pago fiscal del borrador.');$clean=fn($name,$max=null)=>($v=trim((string)$this->request->getPost($name)))===''?null:($max?substr($v,0,$max):$v);$db->table('payment_complements')->where('id',$id)->update(['issue_date'=>$date,'updated_at'=>get_current_utc_time()]);$db->table('payment_complement_payments')->where('id',$payment->id)->update(['payment_form_code'=>$form,'ordering_bank_rfc'=>$clean('ordering_bank_rfc',13),'ordering_bank_name'=>$clean('ordering_bank_name',150),'ordering_account'=>$clean('ordering_account',100),'beneficiary_bank_rfc'=>$clean('beneficiary_bank_rfc',13),'beneficiary_account'=>$clean('beneficiary_account',100),'payment_chain_type'=>$clean('payment_chain_type',2),'payment_certificate'=>$clean('payment_certificate'),'payment_chain'=>$clean('payment_chain'),'payment_signature'=>$clean('payment_signature'),'updated_at'=>get_current_utc_time()]);$db->table('payment_complement_fiscal_snapshots')->where('payment_complement_id',$id)->delete();if(!$db->transStatus())throw new \RuntimeException('No fue posible guardar la información fiscal.');$db->transCommit();return$this->response->setJSON(['success'=>true,'message'=>'Información fiscal guardada.']);}catch(\Throwable$e){$db->transRollback();return$this->response->setStatusCode(422)->setJSON(['success'=>false,'message'=>$e->getMessage()]);}}
    public function addDocument(int$id){$documentId=(int)$this->request->getPost('fiscal_document_id');$amount=$this->request->getPost('amount_paid');try{if(!$documentId)throw new \RuntimeException('Seleccione una factura válida.');$this->service()->addDocument($id,$documentId,$amount,$this->login_user->id);return$this->response->setJSON(['success'=>true,'message'=>'Factura fiscal agregada y reservada.']);}catch(\Throwable$e){$diagnostic=[];try{$diagnostic=$this->service()->addDocumentDiagnostics($id,$documentId,$amount);}catch(\Throwable$diagnosticError){$diagnostic=['diagnostic_error'=>$diagnosticError->getMessage()];}$code=$this->addDocumentValidationCode($e);$diagnostic+=['validation_code'=>$code,'validation_message'=>$e->getMessage(),'exception_class'=>get_class($e),'file'=>$e->getFile(),'line'=>$e->getLine()];log_message('error','PAYMENT_COMPLEMENT_ADD_DOCUMENT_422 {diagnostic}',['diagnostic'=>json_encode($diagnostic,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)]);return$this->response->setStatusCode(422)->setJSON(['success'=>false,'code'=>$code,'message'=>$this->addDocumentPublicMessage($e,$code)]);}}
    public function removeDocument(int$id,int$documentId){try{$this->service()->removeDocument($id,$documentId,$this->login_user->id);return$this->response->setJSON(['success'=>true,'message'=>'Factura retirada; la reserva fue liberada.']);}catch(\Throwable$e){return$this->response->setStatusCode(422)->setJSON(['success'=>false,'message'=>$e->getMessage()]);}}
    public function review(int$id){try{$data=$this->service()->context($id);}catch(\Throwable){throw PageNotFoundException::forPageNotFound();}$inspection=(new PaymentComplementPreflightService(db_connect()))->inspect($id);$data['readiness']=$inspection['review'];$data['preview']=$inspection['snapshot'];$data['preview_error']=$inspection['ready']?null:implode(' ',$inspection['blockers']);$data['ready']=$inspection['ready'];return$this->template->view('payment_complements/review',$data);}
    public function fiscalSnapshot(int$id){try{$review=(new PaymentComplementReadinessService(db_connect()))->check($id);if(!$review['ready'])throw new \RuntimeException('La revisión fiscal contiene errores bloqueantes.');(new PaymentComplementFiscalSnapshotService(db_connect()))->build($id,$this->login_user->id);return$this->response->setJSON(['success'=>true,'redirect_url'=>site_url('payment_complements/preview/'.$id)]);}catch(\Throwable$e){return$this->response->setStatusCode(422)->setJSON(['success'=>false,'message'=>$e->getMessage()]);}}
    public function preview(int$id){try{$data=$this->service()->context($id);$inspection=(new PaymentComplementPreflightService(db_connect()))->inspect($id);if(!$inspection['ready'])return$this->template->view('payment_complements/preview_blocked',['blockers'=>$inspection['blockers']]);$data['payload']=$inspection['snapshot'];$data['print']=(new PaymentComplementPrintDataBuilder())->build($inspection['snapshot']['xml']);$data['logo_html']=$this->paymentComplementLogo($data);return$this->template->view('payment_complements/preview',$data);}catch(\Throwable$e){return$this->template->view('payment_complements/preview_blocked',['blockers'=>[$e->getMessage()]]);}}
    public function stamp(int$id){if(!$this->canStamp())return$this->response->setStatusCode(403)->setJSON(['success'=>false,'message'=>'No tiene permiso para timbrar Complementos.']);try{$result=(new PaymentComplementStampingService(db_connect()))->stamp($id,(int)$this->login_user->id,true);return$this->response->setStatusCode($result['success']?200:422)->setJSON($result+['redirect_url'=>site_url('payment_complements/edit/'.$id)]);}catch(\Throwable$e){log_message('error','Payment Complement stamp failed {id}: {type}',['id'=>$id,'type'=>get_class($e)]);return$this->response->setStatusCode(422)->setJSON(['success'=>false,'message'=>$e->getMessage()]);}}
    private function addDocumentValidationCode(\Throwable$e):string{$message=$e->getMessage();return match(true){str_contains($message,'Seleccione una factura')=>'MISSING_FISCAL_DOCUMENT_ID',str_contains($message,'no es editable')=>'COMPLEMENT_NOT_EDITABLE',str_contains($message,'Pago origen')=>'PAYMENT_SNAPSHOT_MISSING',str_contains($message,'ya no está disponible')=>'FISCAL_DOCUMENT_NOT_ELIGIBLE',str_contains($message,'mayor que cero')=>'INVALID_AMOUNT',str_contains($message,'excede el máximo')=>'AMOUNT_EXCEEDS_FISCAL_AVAILABLE',str_contains(strtolower($message),'cannot be null'),str_contains(strtolower($message),'column')=>'DATABASE_SCHEMA_MISMATCH',default=>'UNEXPECTED_ADD_DOCUMENT_FAILURE'};}
    private function addDocumentPublicMessage(\Throwable$e,string$code):string{return match($code){'DATABASE_SCHEMA_MISMATCH'=>'No fue posible guardar la relación fiscal. Verifique que las migraciones estén aplicadas.','UNEXPECTED_ADD_DOCUMENT_FAILURE'=>'No fue posible agregar la factura fiscal. Consulte la referencia PAYMENT_COMPLEMENT_ADD_DOCUMENT_422 en el log.',default=>$e->getMessage()};}
    private function canStamp():bool{return$this->allowed('fiscal_stamp_sandbox');}
    private function allowed(string$permission):bool{if($this->login_user->is_admin)return true;$permissions=is_array($this->login_user->permissions)?$this->login_user->permissions:(@unserialize((string)$this->login_user->permissions)?:[]);return(bool)get_array_value($permissions,$permission);}
    private function paymentComplementLogo(array$data):string{$companyId=(int)($data['payment']->company_id??0);return function_exists('get_company_logo')?get_company_logo($companyId,'invoice',true):'';}
    public function discard(int$id){try{$this->service()->discard($id,$this->login_user->id,(string)$this->request->getPost('reason'));return$this->response->setJSON(['success'=>true,'message'=>'Borrador descartado; sus reservas fueron liberadas.','redirect_to'=>site_url('payment_complements')]);}catch(\Throwable$e){return$this->response->setStatusCode(422)->setJSON(['success'=>false,'message'=>$e->getMessage()]);}}
}
